type Handler<T> = (request: T) => Result<T> | undefined;   // undefined = forward

function dispatch<T>(chain: readonly Handler<T>[], request: T): Result<T> {
  for (const handler of chain) {
    const result = handler(request);
    if (result !== undefined) return result;      // stop
  }
  return { kind: "unhandled", request };          // typed fallback
}

